import java.util.*;

class Solution {
  public List<Integer> closestKValues(TreeNode root, double target, int k) {
    // inorder gives sorted values; keep a sliding window of the k closest
    LinkedList<Integer> window = new LinkedList<>();
    inorder(root, target, k, window);
    return window;
  }

  private void inorder(TreeNode node, double target, int k, LinkedList<Integer> window) {
    if (node == null) return;
    inorder(node.left, target, k, window);
    if (window.size() < k) window.add(node.val);
    else if (Math.abs(node.val - target) < Math.abs(window.getFirst() - target)) {
      window.removeFirst();
      window.add(node.val);
    } else return; // later values are only farther away
    inorder(node.right, target, k, window);
  }
}
